/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Entry, Messages
 *   Functions: entry, canonical, sortedRecord, sources, establishedBytes
 *   Constants: baselineCatalog, baselineMessages, key, scopedEntry, scopedMessages
 * Tests
 *   - web-listener release copy preserves public and administrator bytes at the full runtime limit
 *   - web-listener messages retain locale completeness, named variables, plain ICU and namespace fences
 *   - web-listener packs enforce their own message-count and byte bounds
 *   - checking and regeneration manage missing, stale and retired web-listener packs
 * @end-catalog */

import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, rm, stat, unlink, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import test, { type TestContext } from 'node:test';

import { buildLocalizationArtifacts, checkLocalizationArtifacts, writeLocalizationArtifacts } from '../../scripts/build-localizations.mjs';

interface Entry { description: string; delivery: string[]; variables: Record<string, string> }
type Messages = Record<string, string>;
const entry = (delivery: string[], variables: Record<string, string> = {}): Entry => ({ description: 'Fixture', delivery, variables });
const baselineCatalog = {
  'admin.existing': entry(['runtime']),
  'admin.pages.title': entry(['web-admin']),
  'shell.home': entry(['runtime'])
};
const baselineMessages = { 'admin.existing': 'Existing administrator copy', 'admin.pages.title': 'Pages', 'shell.home': 'Home' };
const key = 'videos.preview.action';
const scopedEntry = entry(['web-listener'], { title: 'string' });
const scopedMessages = { ...baselineMessages, [key]: 'Preview {title}' };
const canonical = (value: unknown) => JSON.stringify(value, null, 2) + '\n';
const sortedRecord = <T>(value: Record<string, T>) => Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)));

/** Each test owns a complete source catalog and generated tree outside the checkout. */
async function sources(t: TestContext) {
  const root = await mkdtemp(path.join(os.tmpdir(), 'archtree-web-listener-localizations-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  const directory = path.join(root, 'localization');
  await mkdir(path.join(directory, 'locales'), { recursive: true });
  return {
    root,
    write: async (messages: Record<string, Entry>, en: Messages, zh = en) => {
      await writeFile(path.join(directory, 'catalog.json'), canonical({ schemaVersion: 1, locales: {
        'en-US': { nativeName: 'English (United States)', englishName: 'English (United States)' },
        'zh-Hans': { nativeName: '简体中文', englishName: 'Simplified Chinese' }
      }, messages: sortedRecord(messages) }));
      await writeFile(path.join(directory, 'locales/en-US.json'), canonical(sortedRecord(en)));
      await writeFile(path.join(directory, 'locales/zh-Hans.json'), canonical(sortedRecord(zh)));
    }
  };
}

/** Captures all established delivery files, including their existing opaque revisions. */
const establishedBytes = (root: string) => Promise.all(['', 'legacy', 'web-admin'].flatMap(group =>
  ['manifest.json', 'bundles/en-US.json', 'bundles/zh-Hans.json'].map(file =>
    readFile(path.join(root, 'localization/generated', group, file), 'utf8'))));

test('web-listener release copy preserves public and administrator bytes at the full runtime limit', async t => {
  const fixture = await sources(t), catalog: Record<string, Entry> = { ...baselineCatalog }, messages: Messages = { ...baselineMessages };
  for (let index = 0; index < 1_998; index++) {
    const existing = `admin.existing_${String(index).padStart(4, '0')}`;
    catalog[existing] = entry(['runtime']); messages[existing] = 'Existing runtime copy';
  }
  await fixture.write(catalog, messages);
  const before = await writeLocalizationArtifacts(fixture.root), bytes = await establishedBytes(fixture.root);
  assert.equal(before.webListener, undefined);
  await assert.rejects(stat(path.join(fixture.root, 'localization/generated/web-listener')), { code: 'ENOENT' });
  await fixture.write({ ...catalog, [key]: scopedEntry }, { ...messages, [key]: 'Preview {title}' }, { ...messages, [key]: '预览{title}' });
  const after = await writeLocalizationArtifacts(fixture.root);
  assert.equal(Object.keys(after.bundles.get('en-US').messages).length, 2_000);
  assert.deepEqual(after.bundles, before.bundles);
  assert.deepEqual(after.legacy, before.legacy);
  assert.deepEqual(after.webAdmin, before.webAdmin);
  assert.deepEqual(await establishedBytes(fixture.root), bytes);
  assert.deepEqual(after.webListener.bundles.get('zh-Hans').messages, { [key]: '预览{title}' });
  assert.deepEqual(after.webListener.manifest.locales.map(({ locale }: { locale: string }) => locale), ['en-US', 'zh-Hans']);
  const packaged = JSON.parse(await readFile(path.join(fixture.root, 'localization/generated/web-listener/bundles/en-US.json'), 'utf8'));
  assert.deepEqual(packaged.messages, { [key]: 'Preview {title}' });
  assert.equal(after.bundles.get('en-US').messages[key], undefined);
  await checkLocalizationArtifacts(fixture.root);
});

test('web-listener messages retain locale completeness, named variables, plain ICU and namespace fences', async t => {
  const fixture = await sources(t), catalog = { ...baselineCatalog, [key]: scopedEntry };
  for (const [message, error] of [
    ['Preview', /named-variable set/],
    ['{title, date}', /formats title as date, not string/],
    ['Preview {title', /invalid ICU MessageFormat/],
    ['<b>{title}</b>', /plain text rather than rich-text tags/]
  ] as const) {
    await fixture.write(catalog, scopedMessages, { ...baselineMessages, [key]: message });
    await assert.rejects(buildLocalizationArtifacts(fixture.root), error);
  }
  await fixture.write(catalog, scopedMessages, baselineMessages);
  await assert.rejects(buildLocalizationArtifacts(fixture.root), /exactly the catalog message-key set/);
  for (const invalid of ['admin.videos.preview', 'shell.preview']) {
    await fixture.write({ ...baselineCatalog, [invalid]: entry(['web-listener']) }, { ...baselineMessages, [invalid]: 'Invalid scope' });
    await assert.rejects(buildLocalizationArtifacts(fixture.root), /videos namespace for web-listener delivery/);
  }
});

test('web-listener packs enforce their own message-count and byte bounds', async t => {
  const fixture = await sources(t), catalog: Record<string, Entry> = { ...baselineCatalog }, messages: Messages = { ...baselineMessages };
  for (let index = 0; index < 2_001; index++) {
    const name = `videos.copy_${String(index).padStart(4, '0')}`;
    catalog[name] = entry(['web-listener']); messages[name] = 'Scoped copy';
  }
  await fixture.write(catalog, messages);
  await assert.rejects(buildLocalizationArtifacts(fixture.root), /web-listener localization namespace must contain 1–2000 messages/);
  const byteCatalog: Record<string, Entry> = { ...baselineCatalog }, byteMessages: Messages = { ...baselineMessages };
  for (let index = 0; index < 100; index++) {
    const name = `videos.copy_${String(index).padStart(4, '0')}`;
    byteCatalog[name] = entry(['web-listener']); byteMessages[name] = 'x'.repeat(2_500);
  }
  let remaining = 256 * 1024 - 1 - Buffer.byteLength(canonical(sortedRecord(byteMessages)));
  for (const name of Object.keys(byteMessages).filter(name => name.startsWith('videos.'))) {
    const added = Math.min(remaining, 4_000 - byteMessages[name].length);
    byteMessages[name] += 'x'.repeat(added); remaining -= added;
  }
  assert.equal(remaining, 0, 'the canonical source fits while the scoped bundle envelope exceeds its bound');
  await fixture.write(byteCatalog, byteMessages);
  await assert.rejects(buildLocalizationArtifacts(fixture.root), /localization bundle exceeds 262144 bytes/);
});

test('checking and regeneration manage missing, stale and retired web-listener packs', async t => {
  const fixture = await sources(t);
  await fixture.write({ ...baselineCatalog, [key]: scopedEntry }, scopedMessages);
  await writeLocalizationArtifacts(fixture.root);
  const generated = path.join(fixture.root, 'localization/generated/web-listener'), bundle = path.join(generated, 'bundles/en-US.json');
  await unlink(bundle);
  await assert.rejects(checkLocalizationArtifacts(fixture.root), /artifact is missing: localization\/generated\/web-listener\/bundles\/en-US.json/);
  await writeLocalizationArtifacts(fixture.root);
  await writeFile(bundle, '{}\n');
  await assert.rejects(checkLocalizationArtifacts(fixture.root), /artifact is stale: localization\/generated\/web-listener\/bundles\/en-US.json/);
  await writeLocalizationArtifacts(fixture.root);
  await writeFile(path.join(generated, 'bundles/fr.json'), '{}\n');
  await assert.rejects(checkLocalizationArtifacts(fixture.root), /artifact is stale/);
  await writeLocalizationArtifacts(fixture.root);
  await assert.rejects(stat(path.join(generated, 'bundles/fr.json')), { code: 'ENOENT' });
  await checkLocalizationArtifacts(fixture.root);
  await fixture.write(baselineCatalog, baselineMessages);
  await assert.rejects(checkLocalizationArtifacts(fixture.root), /artifact is stale: localization\/generated\/web-listener/);
  await writeLocalizationArtifacts(fixture.root);
  await assert.rejects(stat(path.join(generated, 'manifest.json')), { code: 'ENOENT' });
  await assert.rejects(stat(bundle), { code: 'ENOENT' });
  await checkLocalizationArtifacts(fixture.root);
});
